import { buildSectionQuestBoard, createQuestSeenStore, type SectionQuestBoard } from './sectionQuests';

export const FINANCE_QUEST_SEEN_STORAGE_KEY = 'ci_finance_quests_seen_v1';

export type FinanceQuestInput = {
  hasAssessment?: boolean;
  eligibleCount?: number;
  inProgressCount?: number;
  hasOpenedAdeetie?: boolean;
  hasOpenedGreenLoans?: boolean;
  hasApplication?: boolean;
};

const LEVEL_META = {
  1: { label: 'Starter', caption: 'Run a footprint to unlock matching.' },
  2: { label: 'Exploring', caption: 'Open ADEETIE or green loans.' },
  3: { label: 'Eligible', caption: 'You have matching finance options.' },
  4: { label: 'Finance champ', caption: 'Track applications when you apply.' },
} as const;

export function deriveFinanceQuests(input: FinanceQuestInput): SectionQuestBoard {
  const eligibleCount = Number(input.eligibleCount) || 0;
  const inProgressCount = Number(input.inProgressCount) || 0;

  return buildSectionQuestBoard(
    [
      {
        id: 'finance_baseline',
        title: 'Footprint for finance',
        description: 'Green loans and schemes use your emissions track record.',
        complete: Boolean(input.hasAssessment),
        path: '/carbon-footprint?section=start-assessment',
        ctaLabel: 'Assessment',
      },
      {
        id: 'explore_adeetie',
        title: 'Explore ADEETIE',
        description: 'Check BEE energy-efficiency interest support.',
        complete: Boolean(input.hasOpenedAdeetie) || eligibleCount > 0,
        path: '/adeetie',
        ctaLabel: 'ADEETIE',
      },
      {
        id: 'explore_loans',
        title: 'Explore green loans',
        description: 'See bank-backed options for solar or efficiency.',
        complete: Boolean(input.hasOpenedGreenLoans) || eligibleCount > 0,
        path: '/green-loans',
        ctaLabel: 'Loans',
      },
      {
        id: 'match_option',
        title: 'Get a match',
        description: 'Become eligible for at least one finance option.',
        complete: eligibleCount > 0,
        path: '/finance',
        ctaLabel: 'Matches',
      },
      {
        id: 'track_application',
        title: 'Track an application',
        description: 'Start or open an application when you are ready.',
        complete: Boolean(input.hasApplication) || inProgressCount > 0,
        path: '/gift-applications',
        ctaLabel: 'Applications',
      },
    ],
    LEVEL_META
  );
}

const store = createQuestSeenStore(FINANCE_QUEST_SEEN_STORAGE_KEY);
export const markFinanceQuestSeen = store.markSeen;
export const detectNewFinanceQuestCelebrations = store.detectNewCelebrations;
