import React, { useMemo } from 'react';
import {
  Box,
  Card,
  CardContent,
  Chip,
  LinearProgress,
  Stack,
  Typography,
} from '@mui/material';
import {
  Bar,
  BarChart,
  CartesianGrid,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import CarbonChartFrame from '../shared/CarbonChartFrame';

export type PeerBenchmarkData = {
  industry?: string;
  yourIntensityKgCo2ePerInr?: number;
  peerMedianIntensityKgCo2ePerInr?: number;
  deltaVsPeerPercent?: number;
  ranking?: 'better_than_peer' | 'near_peer' | 'above_peer';
  transactionSampleSize?: number;
};

type Props = {
  data?: PeerBenchmarkData | null;
  loading?: boolean;
};

const rankingLabel: Record<string, string> = {
  better_than_peer: 'Better than peer median',
  near_peer: 'Near peer median',
  above_peer: 'Above peer median',
};

const IndustryPeerBenchmarkDashboard: React.FC<Props> = ({ data, loading = false }) => {
  const chartData = useMemo(() => {
    if (!data) return [];
    return [
      {
        label: 'Your MSME',
        intensity: Number(data.yourIntensityKgCo2ePerInr) || 0,
      },
      {
        label: 'Peer median',
        intensity: Number(data.peerMedianIntensityKgCo2ePerInr) || 0,
      },
    ];
  }, [data]);

  if (loading) {
    return <LinearProgress aria-label="Loading industry peer benchmark" />;
  }

  if (!data) {
    return null;
  }

  const delta = Number(data.deltaVsPeerPercent) || 0;
  const ranking = data.ranking || 'near_peer';

  return (
    <Card variant="outlined" sx={{ mb: 2 }}>
      <CardContent>
        <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 1 }}>
          <Typography variant="h6" component="h2">
            Industry peer benchmark
          </Typography>
          <Chip
            size="small"
            color={ranking === 'above_peer' ? 'warning' : ranking === 'better_than_peer' ? 'success' : 'default'}
            label={rankingLabel[ranking] || ranking}
          />
        </Stack>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          {String(data.industry || 'your sector').replace(/_/g, ' ')} · spend-weighted intensity (kgCO₂e/INR)
          {data.transactionSampleSize ? ` · ${data.transactionSampleSize} transactions sampled` : ''}
        </Typography>
        <CarbonChartFrame
          unitCaption="kgCO₂e per INR spent"
          ariaLabel="Bar chart comparing your emissions intensity to industry peer median"
          height={220}
        >
          <Box sx={{ width: '100%', height: '100%' }}>
            <ResponsiveContainer>
              <BarChart data={chartData} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="label" />
                <YAxis tickFormatter={(v) => v.toFixed(4)} />
                <Tooltip formatter={(value: number) => [`${value.toFixed(6)} kgCO₂e/INR`, 'Intensity']} />
                <Bar dataKey="intensity" fill="#2E7D32" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </Box>
        </CarbonChartFrame>
        <Typography variant="body2" sx={{ mt: 1 }}>
          {delta >= 0
            ? `You are ${Math.abs(delta).toFixed(1)}% above the peer median — focus on Tier 1 activity data and energy efficiency.`
            : `You are ${Math.abs(delta).toFixed(1)}% below the peer median — maintain data quality for assurance.`}
        </Typography>
      </CardContent>
    </Card>
  );
};

export default IndustryPeerBenchmarkDashboard;
