import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  Grid,
  LinearProgress,
  Paper,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import {
  CheckCircle as DoneIcon,
  Factory as FactoryIcon,
} from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import { alpha, useTheme } from '@mui/material/styles';
import ApiService from '../../services/api';
import {
  MSME_OPS_QUEST_SUBTITLE,
  MSME_REGISTRATION_OPS_TITLE,
} from '../../constants/msmeSimplifiedUi';
import {
  deriveOperationsQuests,
  detectNewOpsQuestCelebrations,
  markOpsQuestSeen,
} from '../../utils/operationsQuests';
import {
  AchievementCelebrationDialog,
  type AchievementCelebrationTarget,
} from './AchievementCelebrationDialog';

type RegistrationOpsQuickStartProps = {
  /** Compact for post-registration checklist; full for profile page. */
  compact?: boolean;
  companyName?: string;
};

type QuickUnit = {
  unitId: string;
  name: string;
  location?: string;
  products?: string[];
  productsInput?: string;
  processes?: unknown[];
};

/**
 * Lightweight plant-picture capture for registration / profile.
 * Does not open the Scope stepper — saves electricity, fuel, and site name.
 */
const RegistrationOpsQuickStart: React.FC<RegistrationOpsQuickStartProps> = ({
  compact = false,
  companyName,
}) => {
  const theme = useTheme();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const [plantName, setPlantName] = useState(companyName ? `${companyName} plant` : '');
  const [powerKwh, setPowerKwh] = useState(0);
  const [fuelLiters, setFuelLiters] = useState(0);
  const [units, setUnits] = useState<QuickUnit[]>([]);
  const [employees, setEmployees] = useState<unknown[]>([]);
  const [supplyChain, setSupplyChain] = useState<unknown[]>([]);
  const [hasEstimate, setHasEstimate] = useState(false);
  const [celebration, setCelebration] = useState<AchievementCelebrationTarget | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await ApiService.getManufacturingWorkflow();
      const workflow = response?.data?.workflow || response?.data || {};
      const loadedUnits = Array.isArray(workflow.units) && workflow.units.length > 0
        ? workflow.units
        : [{ unitId: 'unit-1', name: companyName ? `${companyName} plant` : 'Main plant', processes: [] }];
      const ops = workflow.operationsData || {};
      setUnits(loadedUnits);
      setEmployees(Array.isArray(workflow.employees) ? workflow.employees : []);
      setSupplyChain(Array.isArray(workflow.supplyChain) ? workflow.supplyChain : []);
      const loadedName = String(loadedUnits[0]?.name || '').trim();
      setPlantName(loadedName || (companyName ? `${companyName} plant` : ''));
      setPowerKwh(Number(ops.powerConsumptionKwhPerMonth) || 0);
      setFuelLiters(Number(ops.fuelUsageLitersPerMonth) || 0);
      setHasEstimate(
        Number(workflow?.lastEstimate?.totalCO2Emissions) > 0
        || Number(ops?.lastSavedTotalKg) > 0
      );
    } catch {
      setUnits([{ unitId: 'unit-1', name: companyName ? `${companyName} plant` : 'Main plant', processes: [] }]);
    } finally {
      setLoading(false);
    }
  }, [companyName]);

  useEffect(() => {
    void load();
  }, [load]);

  const board = useMemo(
    () =>
      deriveOperationsQuests({
        powerKwhPerMonth: powerKwh,
        fuelLitersPerMonth: fuelLiters,
        primaryUnitName: plantName,
        hasSavedEstimate: hasEstimate || saved,
      }),
    [powerKwh, fuelLiters, plantName, hasEstimate, saved]
  );

  useEffect(() => {
    if (loading) return;
    const pending = detectNewOpsQuestCelebrations(board);
    if (pending.length === 0) return;
    pending.forEach((item) => markOpsQuestSeen(item.id));
    const next = [...pending].sort((a, b) => b.points - a.points)[0];
    setCelebration(next);
  }, [board, loading]);

  const handleSave = async () => {
    setSaving(true);
    setError(null);
    try {
      const nextUnits = (units.length > 0 ? units : [{ unitId: 'unit-1', name: plantName, processes: [] }]).map(
        (unit, index) => ({
          unitId: String(unit.unitId || `unit-${index + 1}`),
          name: index === 0 ? String(plantName || unit.name || `Unit ${index + 1}`).trim() : String(unit.name || `Unit ${index + 1}`).trim(),
          location: String(unit.location || '').trim(),
          products: Array.isArray(unit.products)
            ? unit.products
            : String(unit.productsInput || '')
                .split(',')
                .map((item) => item.trim())
                .filter(Boolean),
          processes: Array.isArray(unit.processes) ? unit.processes : [],
        })
      );

      const response = await ApiService.estimateManufacturingWorkflow({
        units: nextUnits,
        employees,
        supplyChain,
        operationsData: {
          powerConsumptionKwhPerMonth: powerKwh,
          fuelUsageLitersPerMonth: fuelLiters,
          waterUsageKlPerMonth: 0,
          chemicalsUsageKgPerMonth: 0,
        },
        saveWorkflow: true,
      });

      if (response?.data?.estimate) {
        setHasEstimate(true);
      }
      setSaved(true);
      setUnits(nextUnits);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Could not save plant picture');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <Paper variant="outlined" sx={{ p: 2, mb: 2 }}>
        <Typography variant="body2" color="text.secondary">Loading plant picture…</Typography>
        <LinearProgress sx={{ mt: 1 }} />
      </Paper>
    );
  }

  return (
    <Paper
      variant="outlined"
      sx={{
        p: { xs: 2, sm: compact ? 2 : 2.5 },
        mb: 2,
        borderColor: alpha(theme.palette.primary.main, 0.35),
        background: `linear-gradient(135deg, ${alpha(theme.palette.success.main, 0.06)} 0%, ${theme.palette.background.paper} 55%)`,
      }}
    >
      <AchievementCelebrationDialog
        open={Boolean(celebration)}
        achievement={celebration}
        onClose={() => setCelebration(null)}
        headline="Quest complete!"
      />

      <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 0.75 }}>
        <FactoryIcon color="primary" />
        <Typography variant={compact ? 'subtitle1' : 'h6'} sx={{ fontWeight: 800 }}>
          {MSME_REGISTRATION_OPS_TITLE}
        </Typography>
        <Chip size="small" color="primary" label={`Level ${board.level} · ${board.levelLabel}`} />
      </Stack>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5, maxWidth: 640 }}>
        {MSME_OPS_QUEST_SUBTITLE} Optional during registration — upload bills next when ready.
      </Typography>

      <Stack direction="row" spacing={0.75} flexWrap="wrap" useFlexGap sx={{ mb: 1.5 }}>
        {board.quests.filter((q) => q.id !== 'water_drop').map((quest) => (
          <Chip
            key={quest.id}
            size="small"
            icon={quest.complete ? <DoneIcon /> : undefined}
            color={quest.complete ? 'success' : 'default'}
            variant={quest.complete ? 'filled' : 'outlined'}
            label={quest.title}
          />
        ))}
      </Stack>

      <Grid container spacing={1.5}>
        <Grid item xs={12} sm={compact ? 12 : 4}>
          <TextField
            fullWidth
            size="small"
            label="Plant / site name"
            value={plantName}
            onChange={(e) => setPlantName(e.target.value)}
          />
        </Grid>
        <Grid item xs={12} sm={compact ? 6 : 4}>
          <TextField
            fullWidth
            size="small"
            type="number"
            label="Electricity (kWh / month)"
            value={powerKwh || ''}
            onChange={(e) => setPowerKwh(Number(e.target.value) || 0)}
            inputProps={{ min: 0 }}
          />
        </Grid>
        <Grid item xs={12} sm={compact ? 6 : 4}>
          <TextField
            fullWidth
            size="small"
            type="number"
            label="Fuel (litres / month)"
            value={fuelLiters || ''}
            onChange={(e) => setFuelLiters(Number(e.target.value) || 0)}
            inputProps={{ min: 0 }}
          />
        </Grid>
      </Grid>

      {error ? (
        <Alert severity="error" sx={{ mt: 1.5 }}>{error}</Alert>
      ) : null}
      {saved ? (
        <Alert severity="success" sx={{ mt: 1.5 }}>
          Plant picture saved. Next: upload a bill, or open full ops quests anytime.
        </Alert>
      ) : null}

      <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} sx={{ mt: 2 }} flexWrap="wrap" useFlexGap>
        <Button variant="contained" size="small" onClick={() => void handleSave()} disabled={saving}>
          {saving ? 'Saving…' : 'Save plant picture'}
        </Button>
        <Button component={RouterLink} to="/document-upload" variant="outlined" size="small">
          Continue to upload bills
        </Button>
        <Button component={RouterLink} to="/operations" variant="text" size="small">
          Open full quests
        </Button>
      </Stack>

      {!compact ? (
        <Box sx={{ mt: 1.5 }}>
          <LinearProgress variant="determinate" value={board.percent} sx={{ height: 8, borderRadius: 999 }} />
          <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.5 }}>
            {board.completedCount}/{board.totalCount} quests · {board.levelCaption}
          </Typography>
        </Box>
      ) : null}
    </Paper>
  );
};

export default RegistrationOpsQuickStart;
