export const SUPPORT_ROUTE_PREFIX = '/support';

export const isSupportRoute = (pathname: string): boolean =>
  pathname.startsWith(SUPPORT_ROUTE_PREFIX);

export const isPartnerPortalPath = (pathname: string): boolean =>
  pathname === '/partner/login' || pathname.startsWith('/partner/');

export const isInternalPortalPath = (pathname: string): boolean =>
  isAdminRoute(pathname) || isPartnerPortalPath(pathname) || isSupportRoute(pathname);

/** Nav topics hidden until onboarding baseline is complete. */
export const ADVANCED_NAV_PATHS = new Set([
  '/compliance/export',
  '/adeetie',
]);

export interface NavVisibilityInput {
  hasProfile: boolean;
  hasAssessment: boolean;
  hasExportIntent?: boolean;
}

export function filterNavTopicsByProgress(
  topics: NavTopic[],
  input: NavVisibilityInput
): NavTopic[] {
  let filtered = topics;

  // Progressive disclosure: keep the sidebar focused until baseline setup is done.
  if (!input.hasProfile) {
    filtered = filtered.filter(
      (topic) => topic.label === NAV_TOPIC_LABELS.home || topic.label === NAV_TOPIC_LABELS.myCompany
    );
  } else if (!input.hasAssessment) {
    filtered = filtered
      .map((topic) => {
        // Keep Operations + Data connectors visible so tools are not buried.
        if (topic.label === NAV_TOPIC_LABELS.compliance && topic.children) {
          return {
            ...topic,
            children: topic.children.filter((child) => {
              if (child.path.includes('/compliance/export') || child.path === '/buyer-audit') {
                return input.hasExportIntent === true;
              }
              // Hub, India track, and disclosure reports — export stays intent-gated.
              return (
                child.path === '/compliance'
                || child.path.includes('/compliance/india')
                || child.path.includes('/reporting')
              );
            }),
          };
        }
        if (topic.label === NAV_TOPIC_LABELS.finance && topic.children) {
          return {
            ...topic,
            children: topic.children.filter(
              (child) =>
                !child.path.includes('/adeetie') && !child.path.includes('/gift-applications')
            ),
          };
        }
        if (topic.label === NAV_TOPIC_LABELS.emissions && topic.children) {
          return {
            ...topic,
            children: topic.children.filter((child) => !child.path.includes('/carbon-forecasting')),
          };
        }
        if (topic.label === NAV_TOPIC_LABELS.offsets) {
          return null;
        }
        return topic;
      })
      .filter((topic): topic is NavTopic => topic !== null);
  }

  if (SUBSCRIPTION_PLANS_ENABLED && !(input.hasProfile && input.hasAssessment)) {
    filtered = filtered
      .map((topic) => {
        if (topic.label === NAV_TOPIC_LABELS.compliance && topic.children) {
          return {
            ...topic,
            children: topic.children.filter((c) => !c.path.includes('/compliance/export')),
          };
        }
        if (topic.label === NAV_TOPIC_LABELS.finance && topic.children) {
          return {
            ...topic,
            children: topic.children.filter((c) => !c.path.includes('/adeetie')),
          };
        }
        return topic;
      });
  }

  if (!input.hasExportIntent) {
    filtered = filtered.map((topic) => {
      if (topic.label === NAV_TOPIC_LABELS.compliance && topic.children) {
        return {
          ...topic,
          children: topic.children.filter(
            (child) => !child.path.includes('/compliance/export') && child.path !== '/buyer-audit'
          ),
        };
      }
      return topic;
    });
  }

  return filtered;
}

/** Authenticated routes that render without the left navigation pane. */
export const ROUTES_WITHOUT_SIDEBAR = new Set([
  '/',
  '/login',
  '/register',
  '/forgot-password',
  '/privacy-policy',
  '/terms-of-service',
  '/pricing',
  '/about-us',
  '/why-carbon-intelligence',
  '/why-sci',
  '/why-ci',
  '/partners',
  '/partners/api-documentation',
  '/insights',
  '/developers',
  '/partner/login',
  '/partner/dashboard',
  '/admin/login',
  '/support/dashboard',
  '/enterprise/registration',
  '/msme-registration',
]);

export const isEnterpriseAppPath = (pathname: string): boolean =>
  pathname.startsWith('/enterprise');

/** True for MSME workspace routes (not enterprise, admin, partner, or support). */
export const isMsmeAppPath = (pathname: string): boolean =>
  !pathname.startsWith('/enterprise')
  && !pathname.startsWith('/admin')
  && !pathname.startsWith('/partner')
  && !pathname.startsWith('/support');

/** Routes reachable before sign-in (header auth bypass). */
export const PUBLIC_ROUTES = new Set([...Array.from(ROUTES_WITHOUT_SIDEBAR), '/help', '/pricing', '/insights']);

export const isPublicRoute = (pathname: string): boolean => {
  if (PUBLIC_ROUTES.has(pathname)) {
    return true;
  }
  return pathname.startsWith('/insights/') || pathname.startsWith('/carbon-passport/');
};

const OPERATIONS_ROUTE_PATHS = new Set(['/operations']);

export const ADMIN_ROUTE_PREFIX = '/admin';

export function isAdminRoute(pathname: string): boolean {
  return pathname.startsWith(ADMIN_ROUTE_PREFIX);
}

export function shouldShowAppSidebar(pathname: string, isRegistered: boolean): boolean {
  if (!isRegistered) {
    return false;
  }
  if (ROUTES_WITHOUT_SIDEBAR.has(pathname)) {
    return false;
  }
  if (isAdminRoute(pathname)) {
    return false;
  }
  if (isPartnerPortalPath(pathname)) {
    return false;
  }
  if (isSupportRoute(pathname)) {
    return false;
  }
  return true;
}

export function parseNavPath(path: string): { pathname: string; tab: number | null } {
  const [pathname, search = ''] = path.split('?');
  const params = new URLSearchParams(search);
  const tabParam = params.get('tab');
  const tab = tabParam !== null && tabParam !== '' ? Number(tabParam) : null;
  return { pathname, tab: Number.isFinite(tab) ? tab : null };
}

export function isNavPathActive(currentPathname: string, currentSearch: string, navPath: string): boolean {
  const url = new URL(navPath, 'http://local');
  const navPathname = url.pathname;
  const navTab = url.searchParams.get('tab');
  const navSection = url.searchParams.get('section');
  const currentParams = new URLSearchParams(currentSearch);

  if (navPathname === '/operations' && OPERATIONS_ROUTE_PATHS.has(currentPathname)) {
    return true;
  }

  if (currentPathname !== navPathname) {
    return false;
  }

  if (navSection !== null) {
    if (navPathname === '/compliance/india' || navPathname === '/compliance/export') {
      return currentPathname === navPathname && currentParams.get('section') === navSection;
    }
    return currentParams.get('section') === navSection;
  }

  if (navTab !== null) {
    if (currentParams.has('section')) {
      return false;
    }
    const currentTab = currentParams.get('tab');
    if (navTab === '0' && (currentTab === null || currentTab === '')) {
      return true;
    }
    return currentTab === navTab;
  }

  if (currentParams.has('section') || currentParams.has('tab')) {
    return false;
  }

  return true;
}

export function isTopicActive(
  currentPathname: string,
  currentSearch: string,
  topic: NavTopic
): boolean {
  const { pathname: topicPathname } = parseNavPath(topic.path);
  if (
    topicPathname === '/msme-profile' &&
    OPERATIONS_ROUTE_PATHS.has(currentPathname) &&
    currentPathname !== '/msme-profile'
  ) {
    return true;
  }
  if (topicPathname === '/compliance') {
    if (
      currentPathname === '/compliance'
      || currentPathname.startsWith('/compliance/')
      || currentPathname === '/reporting'
      || currentPathname === '/buyer-audit'
    ) {
      return true;
    }
  }
  if (topicPathname === '/carbon-marketplace') {
    if (
      currentPathname === '/carbon-marketplace'
      || currentPathname.startsWith('/carbon-credits')
      || currentPathname.startsWith('/carbon-trading')
    ) {
      return true;
    }
  }
  if (topicPathname === '/data') {
    if (currentPathname === '/document-upload') {
      return true;
    }
  }
  if (currentPathname === topicPathname || currentPathname.startsWith(`${topicPathname}/`)) {
    return true;
  }
  return (
    topic.children?.some((child) => isNavPathActive(currentPathname, currentSearch, child.path)) ??
    false
  );
}
