/** Shared MSME section-quest types and helpers (no redeemable points economy). */

export type SectionQuest = {
  id: string;
  title: string;
  description: string;
  complete: boolean;
  /** Optional UI focus / route hint */
  focus?: string;
  path?: string;
  ctaLabel?: string;
};

export type SectionQuestBoard = {
  quests: SectionQuest[];
  completedCount: number;
  totalCount: number;
  percent: number;
  level: number;
  levelLabel: string;
  levelCaption: string;
  nextQuest: SectionQuest | null;
};

export type SectionLevelMeta = Record<number, { label: string; caption: string }>;

export function buildSectionQuestBoard(
  quests: SectionQuest[],
  levelMeta: SectionLevelMeta
): SectionQuestBoard {
  const completedCount = quests.filter((q) => q.complete).length;
  const totalCount = quests.length;
  const percent = totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0;
  const band =
    completedCount >= 4 ? 4 : completedCount >= 3 ? 3 : completedCount >= 2 ? 2 : 1;
  const meta = levelMeta[band] || levelMeta[1];

  return {
    quests,
    completedCount,
    totalCount,
    percent,
    level: band,
    levelLabel: meta.label,
    levelCaption: meta.caption,
    nextQuest: quests.find((q) => !q.complete) ?? null,
  };
}

export function createQuestSeenStore(storageKey: string) {
  const loadSeen = (): Set<string> => {
    if (typeof window === 'undefined') return new Set();
    try {
      const raw = window.localStorage.getItem(storageKey);
      if (!raw) return new Set();
      const parsed = JSON.parse(raw);
      return new Set(Array.isArray(parsed) ? parsed.filter((id) => typeof id === 'string') : []);
    } catch {
      return new Set();
    }
  };

  const markSeen = (id: string): void => {
    if (typeof window === 'undefined') return;
    const next = loadSeen();
    next.add(id);
    window.localStorage.setItem(storageKey, JSON.stringify(Array.from(next)));
  };

  const detectNewCelebrations = (
    board: SectionQuestBoard
  ): Array<{ id: string; title: string; description: string; points: number }> => {
    const seen = loadSeen();
    return board.quests
      .filter((quest) => quest.complete && !seen.has(quest.id))
      .map((quest) => ({
        id: quest.id,
        title: quest.title,
        description: quest.description,
        points: 0,
      }));
  };

  return { loadSeen, markSeen, detectNewCelebrations };
}
